import{M as e,O as t,f as n,m as r,u as i}from"./runtime-core.esm-bundler-DwmdDY9i.js";import{t as a}from"./plugin-vue_export-helper-BDNMzG2s.js";var o=JSON.parse(`{"path":"/06-etc/infomation/certification-automation.html","title":"인증서 자동교체","lang":"ko-KR","frontmatter":{"description":"인증서 자동교체를 위한 프로토콜 비교 및 Vault PKI 자동화","tag":["certificate","PKI","ACME","SCEP","EST","CMPv2","Vault"],"toc":true,"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"인증서 자동교체\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2025-11-25T01:22:58.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://docmoa.github.io/06-etc/infomation/certification-automation.html"}],["meta",{"property":"og:site_name","content":"docmoa"}],["meta",{"property":"og:title","content":"인증서 자동교체"}],["meta",{"property":"og:description","content":"인증서 자동교체를 위한 프로토콜 비교 및 Vault PKI 자동화"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"ko-KR"}],["meta",{"property":"og:updated_time","content":"2025-11-25T01:22:58.000Z"}],["meta",{"property":"article:tag","content":"Vault"}],["meta",{"property":"article:tag","content":"CMPv2"}],["meta",{"property":"article:tag","content":"EST"}],["meta",{"property":"article:tag","content":"SCEP"}],["meta",{"property":"article:tag","content":"ACME"}],["meta",{"property":"article:tag","content":"PKI"}],["meta",{"property":"article:tag","content":"certificate"}],["meta",{"property":"article:modified_time","content":"2025-11-25T01:22:58.000Z"}]]},"git":{"createdTime":1764033778000,"updatedTime":1764033778000,"contributors":[{"name":"Great-Stone","username":"Great-Stone","email":"hahohh@gmail.com","commits":1,"url":"https://github.com/Great-Stone"}]},"readingTime":{"minutes":48.55,"words":2913},"filePathRelative":"06-etc/infomation/certification-automation.md","excerpt":"\\n<p>인증서 자동교체를 위한 주요 프로토콜(SCEP, EST, ACME, CMPv2)의 비교 및 Vault PKI를 활용한 자동화 방안에 대해 설명합니다.</p>\\n<h2>개요</h2>\\n<p>디지털 인증서는 현대 IT 인프라에서 신원 확인, 데이터 암호화, 통신 보안을 위해 필수적인 요소입니다. 수동으로 인증서를 관리하는 것은 시간이 많이 소요되고 오류가 발생하기 쉬우므로, 인증서의 자동 발급 및 갱신을 위한 다양한 프로토콜이 개발되었습니다.</p>\\n<p>이 문서에서는 인증서의 기본 개념부터 시작하여, 자동 교체를 위한 주요 프로토콜들을 비교하고, HashiCorp Vault를 활용한 PKI 자동화 방안을 다룹니다.</p>"}`),s={name:`certification-automation.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),i(`div`,null,[o[0]||=n(`<h1 id="인증서-자동교체" tabindex="-1"><a class="header-anchor" href="#인증서-자동교체"><span>인증서 자동교체</span></a></h1><p>인증서 자동교체를 위한 주요 프로토콜(SCEP, EST, ACME, CMPv2)의 비교 및 Vault PKI를 활용한 자동화 방안에 대해 설명합니다.</p><h2 id="개요" tabindex="-1"><a class="header-anchor" href="#개요"><span>개요</span></a></h2><p>디지털 인증서는 현대 IT 인프라에서 신원 확인, 데이터 암호화, 통신 보안을 위해 필수적인 요소입니다. 수동으로 인증서를 관리하는 것은 시간이 많이 소요되고 오류가 발생하기 쉬우므로, 인증서의 자동 발급 및 갱신을 위한 다양한 프로토콜이 개발되었습니다.</p><p>이 문서에서는 인증서의 기본 개념부터 시작하여, 자동 교체를 위한 주요 프로토콜들을 비교하고, HashiCorp Vault를 활용한 PKI 자동화 방안을 다룹니다.</p><h2 id="_1-인증서-정의" tabindex="-1"><a class="header-anchor" href="#_1-인증서-정의"><span>1. 인증서 정의</span></a></h2><p><strong>디지털 인증서(Digital Certificate)</strong>는 공개 키 암호화 시스템에서 특정 엔터티(개인, 조직, 서버 등)의 신원을 확인하고 공개 키의 소유권을 증명하는 전자 문서입니다.</p><h3 id="주요-구성-요소" tabindex="-1"><a class="header-anchor" href="#주요-구성-요소"><span>주요 구성 요소</span></a></h3><table><thead><tr><th>구성 요소</th><th>설명</th></tr></thead><tbody><tr><td><strong>주체(Subject)</strong></td><td>인증서의 소유자 정보 (일반 이름, 조직, 국가 등)</td></tr><tr><td><strong>공개 키(Public Key)</strong></td><td>암호화 및 서명 검증에 사용되는 공개 키</td></tr><tr><td><strong>발급자(Issuer)</strong></td><td>인증서를 발급한 인증 기관(CA) 정보</td></tr><tr><td><strong>유효 기간</strong></td><td>인증서의 유효 시작일 및 만료일</td></tr><tr><td><strong>서명</strong></td><td>CA의 개인 키로 생성된 디지털 서명</td></tr></tbody></table><h3 id="인증서의-역할" tabindex="-1"><a class="header-anchor" href="#인증서의-역할"><span>인증서의 역할</span></a></h3><table><thead><tr><th>역할</th><th>설명</th></tr></thead><tbody><tr><td>신원 확인</td><td>인증서 소유자의 신원을 신뢰할 수 있는 제3자(CA)가 보증</td></tr><tr><td>공개 키 배포</td><td>안전하게 공개 키를 배포하고 소유권을 증명</td></tr><tr><td>암호화 통신</td><td>TLS/SSL을 통한 안전한 통신 보장</td></tr><tr><td>데이터 무결성</td><td>디지털 서명을 통한 데이터 변조 방지</td></tr></tbody></table><h2 id="_2-인증서-종류" tabindex="-1"><a class="header-anchor" href="#_2-인증서-종류"><span>2. 인증서 종류</span></a></h2><p>인증서는 검증 수준과 용도에 따라 여러 종류로 분류됩니다.</p><h3 id="_2-1-인증서-검증-수준별-비교" tabindex="-1"><a class="header-anchor" href="#_2-1-인증서-검증-수준별-비교"><span>2.1 인증서 검증 수준별 비교</span></a></h3><table><thead><tr><th>인증서 유형</th><th>검증 수준</th><th>검증 방법</th><th>발급 시간</th><th>용도</th><th>브라우저 표시</th></tr></thead><tbody><tr><td><strong>DV (Domain Validation)</strong></td><td>가장 낮음</td><td>도메인 소유권만 확인 (이메일 또는 DNS 레코드)</td><td>수분~수시간</td><td>개인 웹사이트, 블로그, 개발/테스트 환경</td><td>주소창에 자물쇠 아이콘만 표시</td></tr><tr><td><strong>OV (Organization Validation)</strong></td><td>중간</td><td>도메인 소유권 + 조직 정보 확인</td><td>1~3일</td><td>기업 웹사이트, 전자상거래 사이트</td><td>자물쇠 아이콘 + 조직 정보 확인 가능</td></tr><tr><td><strong>EV (Extended Validation)</strong></td><td>가장 높음</td><td>도메인 소유권 + 조직 정보 + 법적 존재 확인</td><td>3~7일</td><td>금융 기관, 대기업, 정부 기관</td><td>주소창에 조직 이름이 녹색으로 표시</td></tr></tbody></table><h3 id="_2-2-기타-인증서-유형" tabindex="-1"><a class="header-anchor" href="#_2-2-기타-인증서-유형"><span>2.2 기타 인증서 유형</span></a></h3><table><thead><tr><th>인증서 유형</th><th>설명</th><th>용도</th></tr></thead><tbody><tr><td><strong>와일드카드 인증서</strong></td><td><code>*.example.com</code> 형태로 서브도메인 전체에 적용</td><td>여러 서브도메인을 하나의 인증서로 관리</td></tr><tr><td><strong>SAN 인증서</strong></td><td>여러 도메인을 하나의 인증서에 포함</td><td>다중 도메인 웹사이트</td></tr><tr><td><strong>코드 서명 인증서</strong></td><td>소프트웨어 코드의 무결성 검증</td><td>소프트웨어 배포 시 코드 서명</td></tr><tr><td><strong>클라이언트 인증서</strong></td><td>클라이언트 인증용</td><td>mTLS, VPN 클라이언트 인증</td></tr></tbody></table><h2 id="_3-인증서의-쓰임새" tabindex="-1"><a class="header-anchor" href="#_3-인증서의-쓰임새"><span>3. 인증서의 쓰임새</span></a></h2><p>인증서는 다양한 분야에서 보안 통신과 신원 확인을 위해 사용됩니다.</p><table><thead><tr><th>용도</th><th>설명</th><th>주요 기능</th></tr></thead><tbody><tr><td><strong>웹 보안 (HTTPS)</strong></td><td>웹 브라우저와 서버 간의 암호화된 통신</td><td>데이터 암호화, 신원 확인, 데이터 무결성 보장</td></tr><tr><td><strong>이메일 암호화 (S/MIME)</strong></td><td>이메일의 암호화 및 디지털 서명</td><td>이메일 암호화, 발신자 신원 확인, 이메일 무결성 보장</td></tr><tr><td><strong>코드 서명</strong></td><td>소프트웨어 배포 시 코드의 무결성과 출처 보장</td><td>무결성 검증, 출처 확인</td></tr><tr><td><strong>상호 TLS (mTLS)</strong></td><td>클라이언트와 서버 양쪽 모두 인증서를 사용하여 상호 인증</td><td>서비스 간 통신, API 보안, VPN 연결</td></tr><tr><td><strong>문서 서명</strong></td><td>PDF 등 전자 문서의 디지털 서명</td><td>문서 무결성, 발신자 신원 확인</td></tr><tr><td><strong>디바이스 인증</strong></td><td>IoT 디바이스 인증</td><td>디바이스 신원 확인, 안전한 통신</td></tr><tr><td><strong>VPN 인증</strong></td><td>VPN 서버 및 클라이언트 인증</td><td>VPN 연결 보안, 클라이언트 인증</td></tr></tbody></table><h2 id="_4-x-509-설명" tabindex="-1"><a class="header-anchor" href="#_4-x-509-설명"><span>4. X.509 설명</span></a></h2><p><strong>X.509</strong>는 ITU-T에서 정의한 공개 키 인증서의 표준 형식입니다. 현재 대부분의 디지털 인증서가 X.509 표준을 따릅니다.</p><h3 id="_4-1-x-509-인증서-구조" tabindex="-1"><a class="header-anchor" href="#_4-1-x-509-인증서-구조"><span>4.1 X.509 인증서 구조</span></a></h3><p>X.509 인증서는 다음과 같은 주요 필드를 포함합니다:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Certificate</span>
<span class="line">├── Version</span>
<span class="line">├── Serial Number</span>
<span class="line">├── Signature Algorithm</span>
<span class="line">├── Issuer</span>
<span class="line">├── Validity</span>
<span class="line">│   ├── Not Before</span>
<span class="line">│   └── Not After</span>
<span class="line">├── Subject</span>
<span class="line">├── Subject Public Key Info</span>
<span class="line">│   ├── Public Key Algorithm</span>
<span class="line">│   └── Subject Public Key</span>
<span class="line">├── Extensions</span>
<span class="line">│   ├── Key Usage</span>
<span class="line">│   ├── Extended Key Usage</span>
<span class="line">│   ├── Subject Alternative Name (SAN)</span>
<span class="line">│   └── ...</span>
<span class="line">└── Signature Algorithm</span>
<span class="line">└── Signature Value</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-주요-필드-설명" tabindex="-1"><a class="header-anchor" href="#_4-2-주요-필드-설명"><span>4.2 주요 필드 설명</span></a></h3><ul><li><p>Version : 인증서 버전 (보통 v3)</p></li><li><p>Serial Number : CA가 발급한 고유한 일련번호</p></li><li><p>Signature Algorithm : 인증서 서명에 사용된 알고리즘 (예: SHA256withRSA)</p></li><li><p>Issuer : 인증서를 발급한 CA의 정보</p></li><li><p>Validity : 인증서 유효 시작일 및 만료일</p><ul><li><strong>Not Before</strong>: 인증서 유효 시작일</li><li><strong>Not After</strong>: 인증서 만료일</li></ul></li><li><p>Subject : 인증서 소유자의 정보</p><table><thead><tr><th>필드</th><th>약어</th><th>설명</th></tr></thead><tbody><tr><td><strong>Common Name</strong></td><td>CN</td><td>일반 이름 (도메인명 등)</td></tr><tr><td><strong>Organization</strong></td><td>O</td><td>조직명</td></tr><tr><td><strong>Organizational Unit</strong></td><td>OU</td><td>조직 단위</td></tr><tr><td><strong>Locality</strong></td><td>L</td><td>지역</td></tr><tr><td><strong>State</strong></td><td>ST</td><td>주/도</td></tr><tr><td><strong>Country</strong></td><td>C</td><td>국가 코드</td></tr></tbody></table></li><li><p>Subject Public Key Info : 소유자의 공개 키 정보</p></li><li><p>Extensions : 추가 정보 및 제약 조건</p><table><thead><tr><th>확장 필드</th><th>설명</th></tr></thead><tbody><tr><td><strong>Key Usage</strong></td><td>인증서 사용 목적 (디지털 서명, 키 암호화 등)</td></tr><tr><td><strong>Extended Key Usage</strong></td><td>확장된 사용 목적 (서버 인증, 클라이언트 인증 등)</td></tr><tr><td><strong>Subject Alternative Name (SAN)</strong></td><td>추가 도메인명 또는 IP 주소</td></tr></tbody></table></li></ul><h3 id="_4-3-인증서-체인-certificate-chain" tabindex="-1"><a class="header-anchor" href="#_4-3-인증서-체인-certificate-chain"><span>4.3 인증서 체인 (Certificate Chain)</span></a></h3><p>인증서 체인은 신뢰 체인을 구성하는 인증서들의 계층 구조입니다.</p><div class="language-text" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Root CA Certificate (자체 서명)</span>
<span class="line">    ↓</span>
<span class="line">Intermediate CA Certificate (Root CA가 서명)</span>
<span class="line">    ↓</span>
<span class="line">Server Certificate (Intermediate CA가 서명)</span>
<span class="line"></span></code></pre></div><table><thead><tr><th>인증서 유형</th><th>설명</th><th>특징</th></tr></thead><tbody><tr><td><strong>Root CA</strong></td><td>최상위 인증 기관</td><td>자체 서명, 브라우저/OS에 사전 설치됨</td></tr><tr><td><strong>Intermediate CA</strong></td><td>중간 인증 기관</td><td>Root CA가 서명, Root CA와 서버 인증서 사이의 중간 역할</td></tr><tr><td><strong>Server Certificate</strong></td><td>서버 인증서</td><td>Intermediate CA가 서명, 실제 서비스에 사용</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">Intermediate CA나 Root CA가 만료되면 어떻게 되나요?</p><p><strong>1. Root CA 만료 시 영향</strong></p><ul><li>신뢰 체인의 최상위에 있는 Root CA가 만료되면, 해당 Root로부터 발급된 모든 인증서(Intermediate CA 인증서, 최종 서버/클라이언트 인증서 포함)는 운영체제, 브라우저 등에서 &quot;신뢰할 수 없는 인증서&quot;로 간주됩니다.</li><li><strong>Root CA가 자체 서명된 인증서의 유효기간이 지나면</strong> 인증서 체인 전체의 신뢰가 상실되어 서비스 접속 또는 암호화 통신에 실패할 수 있습니다.</li><li>Root CA는 일반적으로 10~30년 이상의 긴 유효기간을 가지며, 만료 이전에 신규 Root CA를 준비하여 체계적으로 교체(갱신 또는 롤오버)해야 합니다.</li></ul><p><strong>2. Intermediate CA 만료 시 영향</strong></p><ul><li>Intermediate CA가 만료되면 해당 Intermediate CA로부터 발급된 <strong>서버/클라이언트(Leaf) 인증서들이 만료 시점 이후 더 이상 신뢰받지 못하며</strong>, 인증서 체인이 끊기게 됩니다.</li><li>이미 발급된 서버 인증서는 Intermediate CA의 만료 전까지만 정상적으로 신뢰됩니다.</li><li><strong>만료 전에 새로운 Intermediate CA를 준비하여 기존과 병행 운영(rollover)한 뒤, 이후 신규 인증서를 새 Intermediate CA로 발급하는 절차</strong>가 일반적입니다.</li></ul><p><strong>3. 대처 방안</strong></p><ul><li>만료 주기를 모니터링하고, 사전에 신규 CA를 발급/배포한 후 중단 없는 신뢰 체인 전환(Rolling Replacement, Rollover)을 계획적으로 수행해야 합니다.</li><li>Root CA의 변경은 각종 단말, 서버, 운영체제, 브라우저 등 Root 인증서를 신뢰하는 모든 환경에 사전 배포가 필요하므로, 적절한 기간을 두고 준비해야 합니다.</li></ul><p><strong>4. 실무 팁</strong></p><ul><li>Root/Intermediate CA의 유효기간, 배포 현황, 만료 일정을 <strong>정기적으로 점검</strong>하세요.</li><li>변경 전후 인증서 체인이 정상적으로 신뢰 및 동작하는지 <strong>테스트 환경에서 꼭 검증</strong>하세요.</li></ul></div><h4 id="intermediate-ca의-역할" tabindex="-1"><a class="header-anchor" href="#intermediate-ca의-역할"><span>Intermediate CA의 역할</span></a></h4><p>Intermediate CA는 Root CA와 서버 인증서 사이의 중간 계층으로, 다음과 같은 중요한 역할을 수행합니다:</p><table><thead><tr><th>역할</th><th>설명</th></tr></thead><tbody><tr><td><strong>보안 격리</strong></td><td>Root CA의 개인 키를 오프라인으로 보관하고, Intermediate CA를 통해 일상적인 인증서 발급 수행</td></tr><tr><td><strong>위험 분산</strong></td><td>Intermediate CA가 손상되더라도 Root CA는 안전하게 보호되며, 해당 Intermediate CA만 폐지 가능</td></tr><tr><td><strong>조직 구조화</strong></td><td>부서별, 지역별, 용도별로 여러 Intermediate CA를 구성하여 관리 체계 구축</td></tr><tr><td><strong>유연한 정책 적용</strong></td><td>각 Intermediate CA마다 다른 인증서 발급 정책 적용 가능</td></tr></tbody></table><h5 id="예시-1-조직-구조-기반-구성" tabindex="-1"><a class="header-anchor" href="#예시-1-조직-구조-기반-구성"><span>예시 1: 조직 구조 기반 구성</span></a></h5><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Root CA</span>
<span class="line">├── Intermediate CA - Production</span>
<span class="line">│   ├── Server Certificate - api.example.com</span>
<span class="line">│   └── Server Certificate - www.example.com</span>
<span class="line">├── Intermediate CA - Development</span>
<span class="line">│   ├── Server Certificate - dev-api.example.com</span>
<span class="line">│   └── Server Certificate - dev-www.example.com</span>
<span class="line">└── Intermediate CA - Internal</span>
<span class="line">    ├── Server Certificate - internal.example.com</span>
<span class="line">    └── Client Certificate - employee.example.com</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="예시-2-지역별-구성" tabindex="-1"><a class="header-anchor" href="#예시-2-지역별-구성"><span>예시 2: 지역별 구성</span></a></h5><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Root CA</span>
<span class="line">├── Intermediate CA - Asia Pacific</span>
<span class="line">│   ├── Server Certificate - ap.example.com</span>
<span class="line">│   └── Server Certificate - ap-api.example.com</span>
<span class="line">├── Intermediate CA - Europe</span>
<span class="line">│   ├── Server Certificate - eu.example.com</span>
<span class="line">│   └── Server Certificate - eu-api.example.com</span>
<span class="line">└── Intermediate CA - Americas</span>
<span class="line">    ├── Server Certificate - us.example.com</span>
<span class="line">    └── Server Certificate - us-api.example.com</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="예시-3-용도별-구성" tabindex="-1"><a class="header-anchor" href="#예시-3-용도별-구성"><span>예시 3: 용도별 구성</span></a></h5><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Root CA</span>
<span class="line">├── Intermediate CA - Web Servers</span>
<span class="line">│   ├── Server Certificate - www.example.com</span>
<span class="line">│   └── Server Certificate - blog.example.com</span>
<span class="line">├── Intermediate CA - API Services</span>
<span class="line">│   ├── Server Certificate - api.example.com</span>
<span class="line">│   └── Server Certificate - gateway.example.com</span>
<span class="line">└── Intermediate CA - Client Authentication</span>
<span class="line">    ├── Client Certificate - mobile-app</span>
<span class="line">    └── Client Certificate - desktop-app</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="실제-사례" tabindex="-1"><a class="header-anchor" href="#실제-사례"><span>실제 사례</span></a></h4><h5 id="사례-1-let-s-encrypt" tabindex="-1"><a class="header-anchor" href="#사례-1-let-s-encrypt"><span>사례 1: Let&#39;s Encrypt</span></a></h5><p>Let&#39;s Encrypt는 공개 CA로, 다음과 같은 체인 구조를 사용합니다:</p><div class="language-text" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ISRG Root X1 (Root CA)</span>
<span class="line">    ↓</span>
<span class="line">R3 (Intermediate CA)</span>
<span class="line">    ↓</span>
<span class="line">Server Certificate (example.com)</span>
<span class="line"></span></code></pre></div><ul><li><strong>Root CA (ISRG Root X1)</strong>: 브라우저에 사전 설치된 최상위 인증서</li><li><strong>Intermediate CA (R3)</strong>: 실제 인증서 발급을 담당하는 중간 인증서</li><li><strong>보안</strong>: Root CA의 개인 키는 오프라인으로 보관하고, Intermediate CA를 통해 일상적인 발급 수행</li></ul><h5 id="사례-2-기업-내부-pki" tabindex="-1"><a class="header-anchor" href="#사례-2-기업-내부-pki"><span>사례 2: 기업 내부 PKI</span></a></h5><p>대기업의 내부 PKI 환경에서는 다음과 같이 구성할 수 있습니다:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Company Root CA (오프라인 보관)</span>
<span class="line">├── Intermediate CA - Production Services</span>
<span class="line">│   ├── Server Certificate - production-api.company.com</span>
<span class="line">│   └── Server Certificate - production-web.company.com</span>
<span class="line">├── Intermediate CA - Development Services</span>
<span class="line">│   ├── Server Certificate - dev-api.company.com</span>
<span class="line">│   └── Server Certificate - dev-web.company.com</span>
<span class="line">└── Intermediate CA - Employee Devices</span>
<span class="line">    ├── Client Certificate - employee-laptop</span>
<span class="line">    └── Client Certificate - employee-mobile</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>구성 이유:</strong></p><ul><li>Production과 Development 환경을 분리하여 보안 정책 차별화</li><li>Employee Devices용 Intermediate CA를 별도로 구성하여 디바이스 인증서 관리</li><li>각 Intermediate CA마다 다른 인증서 유효기간 및 정책 적용</li></ul><h5 id="사례-3-마이크로서비스-아키텍처" tabindex="-1"><a class="header-anchor" href="#사례-3-마이크로서비스-아키텍처"><span>사례 3: 마이크로서비스 아키텍처</span></a></h5><p>마이크로서비스 환경에서는 서비스 간 통신을 위한 mTLS 인증서를 다음과 같이 구성할 수 있습니다:</p><div class="language-text" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Root CA</span>
<span class="line">└── Intermediate CA - Service Mesh</span>
<span class="line">    ├── Server Certificate - frontend-service</span>
<span class="line">    ├── Server Certificate - backend-service</span>
<span class="line">    ├── Server Certificate - database-service</span>
<span class="line">    └── Client Certificate - api-gateway</span>
<span class="line"></span></code></pre></div><p><strong>구성 이유:</strong></p><ul><li>모든 서비스가 동일한 Intermediate CA에서 발급받은 인증서를 사용하여 상호 신뢰</li><li>Service Mesh 환경에서 자동 인증서 발급 및 갱신 용이</li><li>서비스별로 다른 인증서 정책 적용 가능</li></ul><h4 id="intermediate-ca-사용-시-고려사항" tabindex="-1"><a class="header-anchor" href="#intermediate-ca-사용-시-고려사항"><span>Intermediate CA 사용 시 고려사항</span></a></h4><table><thead><tr><th>고려사항</th><th>설명</th></tr></thead><tbody><tr><td><strong>체인 길이</strong></td><td>일반적으로 2-3단계의 Intermediate CA를 사용하며, 너무 깊은 체인은 성능에 영향</td></tr><tr><td><strong>유효기간</strong></td><td>Intermediate CA의 유효기간은 Root CA보다 짧게 설정 (예: Root CA 20년, Intermediate CA 5-10년)</td></tr><tr><td><strong>CRL 배포</strong></td><td>Intermediate CA가 폐지될 경우를 대비한 CRL 배포 계획 필요</td></tr><tr><td><strong>백업 및 복구</strong></td><td>Intermediate CA의 개인 키는 안전하게 백업하고 복구 절차 수립</td></tr></tbody></table><h3 id="_4-4-인증서-형식" tabindex="-1"><a class="header-anchor" href="#_4-4-인증서-형식"><span>4.4 인증서 형식</span></a></h3><table><thead><tr><th>형식</th><th>설명</th><th>확장자</th></tr></thead><tbody><tr><td><strong>PEM (Privacy-Enhanced Mail)</strong></td><td>Base64 인코딩된 텍스트 형식</td><td><code>.pem</code>, <code>.crt</code>, <code>.key</code></td></tr><tr><td><strong>DER (Distinguished Encoding Rules)</strong></td><td>바이너리 형식</td><td><code>.der</code>, <code>.cer</code></td></tr><tr><td><strong>PKCS#12</strong></td><td>개인 키와 인증서를 함께 저장하는 형식</td><td><code>.p12</code>, <code>.pfx</code></td></tr></tbody></table><h2 id="_5-pki-설명" tabindex="-1"><a class="header-anchor" href="#_5-pki-설명"><span>5. PKI 설명</span></a></h2><p><strong>PKI</strong> (Public Key Infrastructure, 공개 키 인프라)는 공개 키 암호화를 기반으로 디지털 인증서를 발급, 관리, 검증, 폐지하는 시스템입니다.</p><h3 id="_5-1-pki-구성-요소" tabindex="-1"><a class="header-anchor" href="#_5-1-pki-구성-요소"><span>5.1 PKI 구성 요소</span></a></h3><table><thead><tr><th>구성 요소</th><th>약어</th><th>설명</th></tr></thead><tbody><tr><td><strong>Certificate Authority</strong></td><td>CA</td><td>인증서를 발급하고 서명하는 신뢰할 수 있는 제3자 기관<br>- <strong>Root CA</strong>: 최상위 인증 기관, 자체 서명된 인증서<br>- <strong>Intermediate CA</strong>: Root CA의 권한을 위임받은 중간 인증 기관</td></tr><tr><td><strong>Registration Authority</strong></td><td>RA</td><td>인증서 발급 요청을 검증하고 CA에 전달하는 기관</td></tr><tr><td><strong>Certificate Revocation List</strong></td><td>CRL</td><td>폐지된 인증서의 목록</td></tr><tr><td><strong>Online Certificate Status Protocol</strong></td><td>OCSP</td><td>인증서의 유효성을 실시간으로 확인하는 프로토콜</td></tr><tr><td><strong>Repository</strong></td><td>-</td><td>인증서와 CRL을 저장하고 배포하는 저장소</td></tr></tbody></table><h3 id="_5-2-인증서-생명주기" tabindex="-1"><a class="header-anchor" href="#_5-2-인증서-생명주기"><span>5.2 인증서 생명주기</span></a></h3>`,65),r(d,{code:``}),o[1]||=n(`<ol><li><strong>생성 요청</strong>: 클라이언트가 인증서 발급 요청</li><li><strong>검증</strong>: RA가 요청자의 신원 및 권한 검증</li><li><strong>발급</strong>: CA가 인증서 생성 및 서명</li><li><strong>활성</strong>: 인증서 사용 중</li><li><strong>갱신</strong>: 만료 전 새 인증서 발급</li><li><strong>폐지</strong>: 문제 발생 시 인증서 폐지 및 CRL 등록</li><li><strong>만료</strong>: 유효기간 종료</li></ol><h3 id="_5-3-pki의-장점" tabindex="-1"><a class="header-anchor" href="#_5-3-pki의-장점"><span>5.3 PKI의 장점</span></a></h3><table><thead><tr><th>장점</th><th>설명</th></tr></thead><tbody><tr><td><strong>자동화</strong></td><td>인증서 발급 및 갱신 자동화 가능</td></tr><tr><td><strong>확장성</strong></td><td>대규모 환경에서도 효율적 관리</td></tr><tr><td><strong>보안</strong></td><td>중앙 집중식 키 및 인증서 관리</td></tr><tr><td><strong>감사</strong></td><td>인증서 발급 및 사용 이력 추적</td></tr></tbody></table><h2 id="_6-인증서-교체를-위한-프로토콜-비교" tabindex="-1"><a class="header-anchor" href="#_6-인증서-교체를-위한-프로토콜-비교"><span>6. 인증서 교체를 위한 프로토콜 비교</span></a></h2><p>인증서의 자동 발급 및 갱신을 위한 주요 프로토콜들을 비교합니다.</p><h3 id="프로토콜-비교표" tabindex="-1"><a class="header-anchor" href="#프로토콜-비교표"><span>프로토콜 비교표</span></a></h3><table><thead><tr><th>프로토콜</th><th>표준</th><th>전송 프로토콜</th><th>인증 방식</th><th>주요 용도</th><th>복잡도</th></tr></thead><tbody><tr><td><strong>SCEP</strong></td><td>RFC 8894</td><td>HTTP/HTTPS</td><td>정적 비밀번호</td><td>네트워크 장비, MDM</td><td>낮음</td></tr><tr><td><strong>EST</strong></td><td>RFC 7030</td><td>HTTPS</td><td>TLS 클라이언트 인증서, 등록 코드</td><td>기업 환경, IoT</td><td>중간</td></tr><tr><td><strong>ACME</strong></td><td>RFC 8555</td><td>HTTPS</td><td>도메인 검증 (HTTP-01, DNS-01)</td><td>웹 서버, 공개 CA</td><td>낮음</td></tr><tr><td><strong>CMPv2</strong></td><td>RFC 4210</td><td>HTTP/HTTPS</td><td>다양한 방식 지원</td><td>기업 PKI, 복잡한 요구사항</td><td>높음</td></tr></tbody></table><h3 id="_6-1-scep-simple-certificate-enrollment-protocol" tabindex="-1"><a class="header-anchor" href="#_6-1-scep-simple-certificate-enrollment-protocol"><span>6.1 SCEP (Simple Certificate Enrollment Protocol)</span></a></h3><p><strong>SCEP</strong>는 네트워크 장비와 모바일 디바이스 관리(MDM) 솔루션에서 널리 사용되는 간단한 인증서 등록 프로토콜입니다.</p><h4 id="정의" tabindex="-1"><a class="header-anchor" href="#정의"><span>정의</span></a></h4><p>SCEP는 Cisco Systems에서 개발한 프로토콜로, 2020년에 RFC 8894로 표준화되었습니다. 정적 비밀번호를 사용한 간단한 인증 방식을 제공합니다.</p><h4 id="주요-특징" tabindex="-1"><a class="header-anchor" href="#주요-특징"><span>주요 특징</span></a></h4><ul><li><strong>단순성</strong>: 구현이 간단하고 이해하기 쉬움</li><li><strong>광범위한 지원</strong>: 네트워크 장비(라우터, 스위치, 방화벽)에서 널리 지원</li><li><strong>정적 비밀번호 인증</strong>: 사전 공유된 비밀번호를 통한 인증</li><li><strong>제한된 기능</strong>: 기본적인 인증서 발급 및 갱신만 지원</li></ul><h4 id="용도" tabindex="-1"><a class="header-anchor" href="#용도"><span>용도</span></a></h4><ul><li>네트워크 장비의 인증서 자동 발급</li><li>MDM 솔루션을 통한 모바일 디바이스 인증서 관리</li><li>VPN 클라이언트 인증서 발급</li></ul><h4 id="동작-방식" tabindex="-1"><a class="header-anchor" href="#동작-방식"><span>동작 방식</span></a></h4>`,16),r(d,{code:``}),o[2]||=n(`<h4 id="장단점-비교" tabindex="-1"><a class="header-anchor" href="#장단점-비교"><span>장단점 비교</span></a></h4><table><thead><tr><th>장점</th><th>단점</th></tr></thead><tbody><tr><td>구현이 간단하고 가볍음</td><td>보안성이 상대적으로 낮음 (정적 비밀번호 사용)</td></tr><tr><td>네트워크 장비에서 광범위하게 지원</td><td>기능이 제한적 (갱신, 폐지 등 고급 기능 부족)</td></tr><tr><td>추가 인프라 구성이 최소화됨</td><td>현대적인 보안 요구사항에 부족</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">SCEP 보안 취약점</p><p>SCEP는 <strong>정적 비밀번호(Static Password)</strong>를 사용하여 인증을 수행합니다. 이는 다음과 같은 보안 취약점을 가집니다:</p><ul><li><strong>비밀번호 유출 위험</strong>: 사전 공유된 비밀번호가 유출되면 누구나 인증서를 발급받을 수 있습니다.</li><li><strong>비밀번호 변경 어려움</strong>: 비밀번호를 변경하려면 모든 클라이언트를 업데이트해야 합니다.</li><li><strong>재사용 공격</strong>: 네트워크 스니핑을 통해 비밀번호가 노출될 수 있습니다.</li></ul><p><strong>권장 사항:</strong></p><ul><li>가능한 경우 EST나 CMPv2 같은 더 안전한 프로토콜 사용을 고려하세요.</li><li>SCEP를 사용해야 하는 경우, 네트워크를 격리하고 정기적으로 비밀번호를 변경하세요.</li><li>프로덕션 환경에서는 추가적인 네트워크 보안 조치를 적용하세요.</li></ul></div><h3 id="_6-2-est-enrollment-over-secure-transport" tabindex="-1"><a class="header-anchor" href="#_6-2-est-enrollment-over-secure-transport"><span>6.2 EST (Enrollment over Secure Transport)</span></a></h3><p><strong>EST</strong>는 SCEP의 보안성을 개선한 프로토콜로, HTTPS를 통해 인증서를 발급받으며 더 강력한 인증 방식을 지원합니다.</p><h4 id="정의-1" tabindex="-1"><a class="header-anchor" href="#정의-1"><span>정의</span></a></h4><p>EST는 RFC 7030으로 표준화된 프로토콜로, HTTPS를 기반으로 하며 TLS 클라이언트 인증서나 등록 코드를 통한 인증을 지원합니다.</p><h4 id="주요-특징-1" tabindex="-1"><a class="header-anchor" href="#주요-특징-1"><span>주요 특징</span></a></h4><ul><li><strong>강력한 보안</strong>: HTTPS 기반 통신</li><li><strong>상호 인증</strong>: TLS 클라이언트 인증서를 통한 상호 인증 지원</li><li><strong>등록 코드</strong>: 일회용 등록 코드를 통한 인증 지원</li><li><strong>확장성</strong>: 다양한 인증 방식 지원</li></ul><h4 id="용도-1" tabindex="-1"><a class="header-anchor" href="#용도-1"><span>용도</span></a></h4><ul><li>기업 환경의 인증서 자동화</li><li>IoT 디바이스 인증서 관리</li><li>보안 요구사항이 높은 환경</li></ul><h4 id="동작-방식-1" tabindex="-1"><a class="header-anchor" href="#동작-방식-1"><span>동작 방식</span></a></h4>`,12),r(d,{code:``}),o[3]||=n(`<h4 id="주요-엔드포인트" tabindex="-1"><a class="header-anchor" href="#주요-엔드포인트"><span>주요 엔드포인트</span></a></h4><ul><li><code>/.well-known/est/cacerts</code>: CA 인증서 조회</li><li><code>/.well-known/est/simpleenroll</code>: 초기 인증서 발급</li><li><code>/.well-known/est/simplereenroll</code>: 인증서 갱신</li><li><code>/.well-known/est/fullcmc</code>: CMC를 통한 고급 작업</li></ul><h4 id="장단점-비교-1" tabindex="-1"><a class="header-anchor" href="#장단점-비교-1"><span>장단점 비교</span></a></h4><table><thead><tr><th>장점</th><th>단점</th></tr></thead><tbody><tr><td>SCEP보다 강력한 보안</td><td>구현이 SCEP보다 복잡</td></tr><tr><td>상호 인증 지원</td><td>지원하는 장비/소프트웨어가 상대적으로 적음</td></tr><tr><td>표준화된 프로토콜 (RFC 7030)</td><td>추가 인프라 구성 필요</td></tr></tbody></table><h3 id="_6-3-acme-automatic-certificate-management-environment" tabindex="-1"><a class="header-anchor" href="#_6-3-acme-automatic-certificate-management-environment"><span>6.3 ACME (Automatic Certificate Management Environment)</span></a></h3><p><strong>ACME</strong>는 Let&#39;s Encrypt에서 개발한 프로토콜로, 웹 서버의 인증서 자동 발급 및 갱신을 위해 설계되었습니다. RFC 8555로 표준화되었습니다.</p><h4 id="정의-2" tabindex="-1"><a class="header-anchor" href="#정의-2"><span>정의</span></a></h4><p>ACME는 도메인 검증을 통해 공개 CA로부터 무료 TLS 인증서를 자동으로 발급받고 갱신할 수 있게 해주는 프로토콜입니다.</p><h4 id="주요-특징-2" tabindex="-1"><a class="header-anchor" href="#주요-특징-2"><span>주요 특징</span></a></h4><ul><li><strong>완전 자동화</strong>: 인증서 발급부터 갱신까지 전 과정 자동화</li><li><strong>도메인 검증</strong>: HTTP-01, DNS-01, TLS-ALPN-01 등 다양한 검증 방식</li><li><strong>무료 인증서</strong>: Let&#39;s Encrypt를 통한 무료 인증서 발급</li><li><strong>광범위한 지원</strong>: 대부분의 웹 서버 및 공개 CA에서 지원</li></ul><h4 id="용도-2" tabindex="-1"><a class="header-anchor" href="#용도-2"><span>용도</span></a></h4><ul><li>웹 서버의 TLS 인증서 자동 관리</li><li>공개 웹사이트의 HTTPS 인증서 발급</li><li>개발/테스트 환경의 인증서 자동화</li></ul><h4 id="동작-방식-2" tabindex="-1"><a class="header-anchor" href="#동작-방식-2"><span>동작 방식</span></a></h4>`,13),r(d,{code:``}),o[4]||=n(`<h4 id="도메인-검증-방식" tabindex="-1"><a class="header-anchor" href="#도메인-검증-방식"><span>도메인 검증 방식</span></a></h4><ol><li><strong>HTTP-01</strong>: 웹 서버의 특정 경로에 토큰 파일을 배치하여 검증</li><li><strong>DNS-01</strong>: DNS TXT 레코드를 추가하여 검증</li><li><strong>TLS-ALPN-01</strong>: TLS 핸드셰이크 중 검증</li></ol><h4 id="장단점-비교-2" tabindex="-1"><a class="header-anchor" href="#장단점-비교-2"><span>장단점 비교</span></a></h4><table><thead><tr><th>장점</th><th>단점</th></tr></thead><tbody><tr><td>완전 자동화된 인증서 관리</td><td>공개 도메인에만 적용 가능 (내부 도메인 제한적)</td></tr><tr><td>무료 인증서 제공 (Let&#39;s Encrypt)</td><td>도메인 검증만 지원 (조직 검증 불가)</td></tr><tr><td>광범위한 도구 및 라이브러리 지원</td><td>주로 TLS/웹 인증서에 특화</td></tr><tr><td>표준화된 프로토콜</td><td></td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">ACME 사용 제한사항</p><p>ACME는 주로 <strong>공개 CA(Let&#39;s Encrypt 등)</strong>와 함께 사용되며, 다음과 같은 제한사항이 있습니다:</p><ul><li><strong>공개 도메인 필요</strong>: ACME는 공개적으로 접근 가능한 도메인에 대한 검증만 지원합니다. 내부 도메인(예: <code>.local</code>, <code>.internal</code>)은 일반적으로 사용할 수 없습니다.</li><li><strong>도메인 검증만 지원</strong>: 조직 검증(OV)이나 확장 검증(EV) 인증서는 발급할 수 없습니다.</li><li><strong>인터넷 접근 필요</strong>: Challenge 검증을 위해 CA 서버가 도메인에 HTTP 또는 DNS로 접근할 수 있어야 합니다.</li></ul><p><strong>대안:</strong></p><ul><li>내부 도메인이나 프라이빗 CA가 필요한 경우 Vault PKI Engine의 REST API나 EST/CMPv2 프로토콜을 사용하세요.</li><li>Vault PKI Engine은 ACME를 지원하지만, 내부 CA로부터 인증서를 발급받을 수 있습니다.</li></ul></div><h3 id="_6-4-cmpv2-certificate-management-protocol-v2" tabindex="-1"><a class="header-anchor" href="#_6-4-cmpv2-certificate-management-protocol-v2"><span>6.4 CMPv2 (Certificate Management Protocol v2)</span></a></h3><p><strong>CMPv2</strong>는 가장 포괄적인 인증서 관리 프로토콜로, 기업 환경의 복잡한 인증서 관리 요구사항을 충족하기 위해 설계되었습니다.</p><h4 id="정의-3" tabindex="-1"><a class="header-anchor" href="#정의-3"><span>정의</span></a></h4><p>CMPv2는 RFC 4210으로 표준화된 프로토콜로, 인증서의 발급, 갱신, 폐지, 키 복구 등 다양한 인증서 관리 작업을 지원합니다.</p><h4 id="주요-특징-3" tabindex="-1"><a class="header-anchor" href="#주요-특징-3"><span>주요 특징</span></a></h4><ul><li><strong>포괄적 기능</strong>: 인증서 생명주기 전 과정 지원</li><li><strong>유연한 인증</strong>: 다양한 인증 방식 지원</li><li><strong>키 복구</strong>: 키 복구 기능 지원</li><li><strong>RA 지원</strong>: Registration Authority와의 통합</li></ul><h4 id="용도-3" tabindex="-1"><a class="header-anchor" href="#용도-3"><span>용도</span></a></h4><ul><li>기업 PKI 환경</li><li>복잡한 인증서 관리 요구사항</li><li>키 복구가 필요한 환경</li><li>다양한 인증서 유형 관리</li></ul><h4 id="동작-방식-3" tabindex="-1"><a class="header-anchor" href="#동작-방식-3"><span>동작 방식</span></a></h4>`,14),r(d,{code:``}),o[5]||=n(`<h4 id="주요-메시지-유형" tabindex="-1"><a class="header-anchor" href="#주요-메시지-유형"><span>주요 메시지 유형</span></a></h4><ul><li><strong>Initialization Request/Response</strong>: 초기 인증서 발급</li><li><strong>Certification Request/Response</strong>: 인증서 발급 요청/응답</li><li><strong>Key Update Request/Response</strong>: 키 갱신</li><li><strong>Revocation Request/Response</strong>: 인증서 폐지</li><li><strong>Cross-Certification Request/Response</strong>: 교차 인증</li></ul><h4 id="장단점-비교-3" tabindex="-1"><a class="header-anchor" href="#장단점-비교-3"><span>장단점 비교</span></a></h4><table><thead><tr><th>장점</th><th>단점</th></tr></thead><tbody><tr><td>가장 포괄적인 기능 제공</td><td>구현이 매우 복잡</td></tr><tr><td>기업 환경에 적합</td><td>지원하는 소프트웨어가 제한적</td></tr><tr><td>키 복구 등 고급 기능 지원</td><td>높은 학습 곡선</td></tr><tr><td>표준화된 프로토콜</td><td>과도한 기능으로 인한 오버헤드</td></tr></tbody></table><h2 id="_7-vault-pki" tabindex="-1"><a class="header-anchor" href="#_7-vault-pki"><span>7. Vault PKI</span></a></h2><p>HashiCorp Vault는 PKI 시크릿 엔진을 통해 인증서의 발급, 관리, 자동 갱신을 지원합니다.</p><h3 id="_7-1-pki-engine" tabindex="-1"><a class="header-anchor" href="#_7-1-pki-engine"><span>7.1 PKI Engine</span></a></h3><p>Vault의 PKI 시크릿 엔진은 자체 서명된 CA 인증서를 생성하고, 이를 기반으로 인증서를 발급할 수 있는 기능을 제공합니다.</p><h4 id="개요-1" tabindex="-1"><a class="header-anchor" href="#개요-1"><span>개요</span></a></h4><p>Vault PKI Secrets Engine은 X.509 인증서의 전체 생명주기를 관리하는 종합적인 PKI 솔루션입니다. Root CA와 Intermediate CA를 생성하고, 동적으로 인증서를 발급하며, 인증서 폐지 및 CRL(Certificate Revocation List) 관리를 지원합니다.</p><h4 id="지원-범위" tabindex="-1"><a class="header-anchor" href="#지원-범위"><span>지원 범위</span></a></h4><table><thead><tr><th>기능</th><th>설명</th></tr></thead><tbody><tr><td><strong>Root CA 생성</strong></td><td>자체 서명된 Root CA 인증서 및 개인 키 생성</td></tr><tr><td><strong>Intermediate CA 관리</strong></td><td>Intermediate CA 생성, 서명, 관리</td></tr><tr><td><strong>동적 인증서 발급</strong></td><td>Role 기반 또는 CSR 서명을 통한 인증서 발급</td></tr><tr><td><strong>인증서 폐지</strong></td><td>인증서 폐지 및 CRL 생성/배포</td></tr><tr><td><strong>인증서 갱신</strong></td><td>만료 전 인증서 자동 갱신 지원</td></tr><tr><td><strong>Role 기반 정책</strong></td><td>도메인, TTL, 키 사용 등 세밀한 인증서 발급 정책 정의</td></tr><tr><td><strong>다중 마운트</strong></td><td>여러 PKI 엔진을 다른 경로에 마운트하여 독립적으로 운영</td></tr><tr><td><strong>인증서 메타데이터</strong></td><td>인증서 발급 이력 및 메타데이터 추적 (Enterprise 기능)</td></tr></tbody></table><h4 id="지원-프로토콜" tabindex="-1"><a class="header-anchor" href="#지원-프로토콜"><span>지원 프로토콜</span></a></h4><p>Vault PKI Engine은 다음과 같은 표준 프로토콜을 지원합니다:</p><table><thead><tr><th>프로토콜</th><th>설명</th><th>버전</th><th>라이선스</th></tr></thead><tbody><tr><td><strong>REST API</strong></td><td>Vault의 기본 HTTP API를 통한 인증서 관리</td><td>모든 버전</td><td>Open Source / Enterprise</td></tr><tr><td><strong>ACME (Automatic Certificate Management Environment)</strong></td><td>RFC 8555 기반 자동 인증서 발급 및 갱신 프로토콜</td><td>Vault 1.14+</td><td>Open Source / Enterprise</td></tr><tr><td><strong>EST (Enrollment over Secure Transport)</strong></td><td>RFC 7030 기반 인증서 등록 프로토콜 (Beta)</td><td>Vault 1.16+</td><td><strong>Enterprise만</strong></td></tr><tr><td><strong>CMPv2 (Certificate Management Protocol v2)</strong></td><td>RFC 4210 기반 포괄적 인증서 관리 프로토콜</td><td>Vault 1.18+</td><td><strong>Enterprise만</strong></td></tr><tr><td><strong>SCEP (Simple Certificate Enrollment Protocol)</strong></td><td>RFC 8894 기반 간단한 인증서 등록 프로토콜</td><td>최신 버전</td><td><strong>Enterprise만</strong></td></tr></tbody></table><h5 id="acme-automatic-certificate-management-environment-지원" tabindex="-1"><a class="header-anchor" href="#acme-automatic-certificate-management-environment-지원"><span>ACME (Automatic Certificate Management Environment) 지원</span></a></h5><p>Vault PKI Engine은 ACME 프로토콜을 통해 자동 인증서 발급 및 갱신을 지원합니다.</p><p><strong>주요 기능:</strong></p><ul><li>RFC 8555 표준 준수</li><li>HTTP-01, DNS-01, TLS-ALPN-01 도메인 검증 방식 지원</li><li>EAB (External Account Binding) 지원</li><li>Role 기반 인증서 발급 정책 적용</li></ul><p><strong>설정 예시:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># ACME 활성화 (기본적으로 활성화됨)</span></span>
<span class="line">vault <span class="token function">write</span> pki/config/acme <span class="token assign-left variable">enabled</span><span class="token operator">=</span>true</span>
<span class="line"></span>
<span class="line"><span class="token comment"># ACME 응답 헤더 설정</span></span>
<span class="line">vault secrets tune <span class="token punctuation">\\</span></span>
<span class="line">  -allowed-response-headers<span class="token operator">=</span><span class="token string">&quot;Replay-Nonce&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  -allowed-response-headers<span class="token operator">=</span><span class="token string">&quot;Link&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  -allowed-response-headers<span class="token operator">=</span><span class="token string">&quot;Location&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  pki</span>
<span class="line"></span>
<span class="line"><span class="token comment"># EAB 토큰 생성</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-f</span> pki/roles/my-role/acme/new-eab</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>주요 엔드포인트:</strong></p><ul><li><code>/v1/pki/roles/{role}/acme/directory</code>: ACME 디렉토리</li><li><code>/v1/pki/roles/{role}/acme/new-account</code>: 계정 생성</li><li><code>/v1/pki/roles/{role}/acme/new-order</code>: 주문 생성</li><li><code>/v1/pki/roles/{role}/acme/challenge/{challenge_id}</code>: Challenge 처리</li></ul><h5 id="est-enrollment-over-secure-transport-지원" tabindex="-1"><a class="header-anchor" href="#est-enrollment-over-secure-transport-지원"><span>EST (Enrollment over Secure Transport) 지원</span></a></h5><p>Vault PKI Engine은 EST 프로토콜을 통해 인증서 등록을 지원합니다. <strong>Enterprise 버전에서만 사용 가능하며, 현재 Beta 기능입니다.</strong></p><p><strong>주요 기능:</strong></p><ul><li><code>/.well-known/est/cacerts</code>: CA 인증서 조회</li><li><code>/.well-known/est/simpleenroll</code>: 초기 인증서 발급</li><li><code>/.well-known/est/simplereenroll</code>: 인증서 갱신</li><li>HTTP 기반 클라이언트 인증 및 TLS 클라이언트 인증서 인증 지원</li></ul><p><strong>제한사항:</strong></p><ul><li>Full CMC는 지원하지 않음</li><li>서버 측 키 생성은 지원하지 않음</li><li>CSR 속성 엔드포인트는 지원하지 않음</li></ul><p><strong>설정 예시:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">vault <span class="token function">write</span> pki/config/est -<span class="token operator">&lt;&lt;</span><span class="token string">EOC</span>
<span class="line">{</span>
<span class="line">  &quot;enabled&quot;: true,</span>
<span class="line">  &quot;default_mount&quot;: true,</span>
<span class="line">  &quot;default_path_policy&quot;: &quot;sign-verbatim&quot;,</span>
<span class="line">  &quot;authenticators&quot;: {</span>
<span class="line">    &quot;cert&quot;: {</span>
<span class="line">      &quot;accessor&quot;: &quot;auth_cert_xxx&quot;</span>
<span class="line">    }</span>
<span class="line">  }</span>
<span class="line">}</span>
<span class="line">EOC</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="scep-simple-certificate-enrollment-protocol-지원" tabindex="-1"><a class="header-anchor" href="#scep-simple-certificate-enrollment-protocol-지원"><span>SCEP (Simple Certificate Enrollment Protocol) 지원</span></a></h5><p>Vault PKI Engine은 SCEP 프로토콜을 통해 간단한 인증서 등록을 지원합니다. <strong>Enterprise 버전에서만 사용 가능합니다.</strong></p><p><strong>주요 기능:</strong></p><ul><li>RFC 8894 표준 준수</li><li>정적 비밀번호 기반 인증</li><li>Microsoft Intune과의 통합 지원</li><li>정적 Challenge 및 외부 검증 지원</li></ul><p><strong>인증 방식:</strong></p><ul><li><strong>Static Challenge</strong>: 사전 공유된 비밀번호를 통한 인증</li><li><strong>External Validation</strong>: Microsoft Intune 등 외부 서비스를 통한 검증</li></ul><p><strong>설정 예시:</strong></p><div class="language-bash line-numbers-mode has-collapsed-lines collapsed" data-highlighter="prismjs" data-ext="sh" style="--vp-collapsed-lines:20;"><pre><code class="language-bash"><span class="line"><span class="token comment"># Static Challenge 방식</span></span>
<span class="line">vault <span class="token function">write</span> pki_int/config/scep <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">enabled</span><span class="token operator">=</span>true <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">default_path_policy</span><span class="token operator">=</span><span class="token string">&quot;role:scep-clients&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">authenticators</span><span class="token operator">=</span><span class="token string">&#39;{</span>
<span class="line">    &quot;scep&quot;: {</span>
<span class="line">      &quot;accessor&quot;: &quot;\${SCEP_ACCESSOR}&quot;,</span>
<span class="line">      &quot;scep_role&quot;: &quot;static-challenge-1&quot;</span>
<span class="line">    },</span>
<span class="line">    &quot;cert&quot;: {</span>
<span class="line">      &quot;accessor&quot;: &quot;\${CERT_ACCESSOR}&quot;,</span>
<span class="line">      &quot;cert_role&quot;: &quot;scep-ca&quot;</span>
<span class="line">    }</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Intune 통합 방식</span></span>
<span class="line">vault <span class="token function">write</span> pki_int/config/scep <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">enabled</span><span class="token operator">=</span>true <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">default_path_policy</span><span class="token operator">=</span><span class="token string">&quot;role:scep-clients&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">authenticators</span><span class="token operator">=</span><span class="token string">&#39;{</span>
<span class="line">    &quot;scep&quot;: {</span>
<span class="line">      &quot;accessor&quot;: &quot;\${SCEP_ACCESSOR}&quot;,</span>
<span class="line">      &quot;scep_role&quot;: &quot;intune&quot;</span>
<span class="line">    }</span>
<span class="line">  }&#39;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">external_validation</span><span class="token operator">=</span><span class="token string">&#39;{</span>
<span class="line">    &quot;intune&quot;: {</span>
<span class="line">      &quot;tenant_id&quot;: &quot;\${INTUNE_TENANT_ID}&quot;,</span>
<span class="line">      &quot;client_id&quot;: &quot;\${INTUNE_CLIENT_ID}&quot;,</span>
<span class="line">      &quot;client_secret&quot;: &quot;\${INTUNE_CLIENT_SECRET}&quot;</span>
<span class="line">    }</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div><div class="collapsed-lines"></div></div><h5 id="cmpv2-certificate-management-protocol-v2-지원" tabindex="-1"><a class="header-anchor" href="#cmpv2-certificate-management-protocol-v2-지원"><span>CMPv2 (Certificate Management Protocol v2) 지원</span></a></h5><p>Vault PKI Engine은 CMPv2 프로토콜을 통해 포괄적인 인증서 관리를 지원합니다. <strong>Enterprise 버전에서만 사용 가능합니다.</strong></p><p><strong>주요 기능:</strong></p><ul><li>초기 인증서 발급 (Initialization Request/Response)</li><li>인증서 발급 요청/응답 (Certification Request/Response)</li><li>키 갱신 (Key Update Request/Response)</li><li>인증서 폐지 (Revocation Request/Response)</li><li>교차 인증 (Cross-Certification Request/Response)</li></ul><p><strong>설정 예시:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># PKI 마운트 튜닝</span></span>
<span class="line">vault secrets tune <span class="token punctuation">\\</span></span>
<span class="line">  -allowed-response-headers<span class="token operator">=</span><span class="token string">&quot;Content-Transfer-Encoding&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  -allowed-response-headers<span class="token operator">=</span><span class="token string">&quot;Content-Length&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  -allowed-response-headers<span class="token operator">=</span><span class="token string">&quot;WWW-Authenticate&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  -delegated-auth-accessors<span class="token operator">=</span><span class="token string">&quot;auth_cert_xxx&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  -trim-request-trailing-slashes<span class="token operator">=</span><span class="token string">&quot;true&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  pki</span>
<span class="line"></span>
<span class="line"><span class="token comment"># CMPv2 활성화</span></span>
<span class="line">vault <span class="token function">write</span> pki/config/cmp <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">enabled</span><span class="token operator">=</span>true <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">default_path_policy</span><span class="token operator">=</span><span class="token string">&quot;role:example-role&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token assign-left variable">authenticators</span><span class="token operator">=</span><span class="token string">&#39;{&quot;cert&quot;:{&quot;accessor&quot;:&quot;auth_cert_xxx&quot;}}&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>CMPv2 제한사항:</strong></p><ul><li>PasswordBasedMac 기반 기본 인증 방식은 지원하지 않음</li><li>폐지 기능은 지원하지 않음</li><li>CMP를 통한 CRL 조회는 지원하지 않음</li><li>CA 생성/업데이트 작업은 지원하지 않음</li><li>Certificate Metadata 및 CIEPS와 통합되지 않음</li></ul><h4 id="주요-특징-4" tabindex="-1"><a class="header-anchor" href="#주요-특징-4"><span>주요 특징</span></a></h4><table><thead><tr><th>특징</th><th>설명</th></tr></thead><tbody><tr><td><strong>동적 인증서 생성</strong></td><td>요청 시마다 새로운 인증서와 키 쌍을 동적으로 생성</td></tr><tr><td><strong>자동 갱신</strong></td><td>TTL 기반 자동 인증서 갱신 지원</td></tr><tr><td><strong>세밀한 정책 제어</strong></td><td>Role을 통한 도메인, TTL, 키 사용 등 세밀한 제어</td></tr><tr><td><strong>보안 강화</strong></td><td>Root CA 개인 키를 안전하게 보관하고, Intermediate CA를 통한 일상적 발급</td></tr><tr><td><strong>감사 로깅</strong></td><td>모든 인증서 발급 및 폐지 작업에 대한 상세한 감사 로그</td></tr><tr><td><strong>다중 환경 지원</strong></td><td>Production, Development 등 여러 환경을 독립적으로 관리</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">Root CA 개인 키 관리 및 CA 만료 모니터링</p><p><strong>Root CA 개인 키 관리:</strong></p><ul><li>Root CA의 개인 키는 <strong>절대 유출되어서는 안 됩니다</strong>. 유출 시 전체 PKI 인프라가 위험에 처합니다.</li><li>Root CA 개인 키는 <strong>오프라인으로 보관</strong>하고, 일상적인 인증서 발급에는 Intermediate CA를 사용하세요.</li><li>Root CA는 Vault 내부에 저장되지만, 추가적인 백업 및 암호화 보호를 고려하세요.</li></ul><p><strong>CA 만료 자동 감지 불가:</strong></p><ul><li>Vault PKI Engine은 <strong>CA 만료를 자동으로 감지하지 않습니다</strong>. CA가 만료되면 인증서 발급이 실패합니다.</li><li>정기적으로 CA 만료일을 확인하고, 만료 전에 새 CA를 준비하는 모니터링 시스템을 구축하세요.</li><li>CA 만료일 확인 방법은 <a href="#73-ca-%EB%A7%8C%EB%A3%8C-%EB%B0%8F-%EA%B0%B1%EC%8B%A0">7.3 CA 만료 및 갱신</a> 섹션을 참고하세요.</li></ul></div><details class="hint-container details"><summary>PKI Engine 설정 예시</summary><h4 id="pki-엔진-활성화" tabindex="-1"><a class="header-anchor" href="#pki-엔진-활성화"><span>PKI 엔진 활성화</span></a></h4><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># PKI 시크릿 엔진 활성화</span></span>
<span class="line">vault secrets <span class="token builtin class-name">enable</span> <span class="token parameter variable">-path</span><span class="token operator">=</span>pki pki</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 최대 TTL 설정 (10년)</span></span>
<span class="line">vault secrets tune -max-lease-ttl<span class="token operator">=</span>87600h pki</span>
<span class="line"></span></code></pre></div><h4 id="root-ca-생성" tabindex="-1"><a class="header-anchor" href="#root-ca-생성"><span>Root CA 생성</span></a></h4><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Root CA 인증서 생성</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-field</span><span class="token operator">=</span>certificate pki/root/generate/internal <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">common_name</span><span class="token operator">=</span><span class="token string">&quot;example.com&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">ttl</span><span class="token operator">=</span>87600h <span class="token operator">&gt;</span> CA_cert.crt</span>
<span class="line"></span>
<span class="line"><span class="token comment"># CA 및 CRL URL 설정</span></span>
<span class="line">vault <span class="token function">write</span> pki/config/urls <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">issuing_certificates</span><span class="token operator">=</span><span class="token string">&quot;http://127.0.0.1:8200/v1/pki/ca&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">crl_distribution_points</span><span class="token operator">=</span><span class="token string">&quot;http://127.0.0.1:8200/v1/pki/crl&quot;</span></span>
<span class="line"></span></code></pre></div><h4 id="intermediate-ca-구성" tabindex="-1"><a class="header-anchor" href="#intermediate-ca-구성"><span>Intermediate CA 구성</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Intermediate CA 엔진 활성화</span></span>
<span class="line">vault secrets <span class="token builtin class-name">enable</span> <span class="token parameter variable">-path</span><span class="token operator">=</span>pki_int pki</span>
<span class="line">vault secrets tune -max-lease-ttl<span class="token operator">=</span>43800h pki_int</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Intermediate CA CSR 생성</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-format</span><span class="token operator">=</span>json pki_int/intermediate/generate/internal <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">common_name</span><span class="token operator">=</span><span class="token string">&quot;example.com Intermediate Authority&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.data.csr&#39;</span> <span class="token operator">&gt;</span> pki_intermediate.csr</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Root CA로 Intermediate CA 서명</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-format</span><span class="token operator">=</span>json pki/root/sign-intermediate <span class="token assign-left variable">csr</span><span class="token operator">=</span>@pki_intermediate.csr <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">format</span><span class="token operator">=</span>pem_bundle <span class="token assign-left variable">ttl</span><span class="token operator">=</span><span class="token string">&quot;43800h&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.data.certificate&#39;</span> <span class="token operator">&gt;</span> intermediate.cert.pem</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Intermediate CA 설정</span></span>
<span class="line">vault <span class="token function">write</span> pki_int/intermediate/set-signed <span class="token assign-left variable">certificate</span><span class="token operator">=</span>@intermediate.cert.pem</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="role-생성" tabindex="-1"><a class="header-anchor" href="#role-생성"><span>Role 생성</span></a></h4><p>Role은 인증서 발급 정책을 정의합니다.</p><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">vault <span class="token function">write</span> pki/roles/example-dot-com <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">allowed_domains</span><span class="token operator">=</span>example.com <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">allow_subdomains</span><span class="token operator">=</span>true <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">max_ttl</span><span class="token operator">=</span>72h</span>
<span class="line"></span></code></pre></div><h4 id="인증서-발급" tabindex="-1"><a class="header-anchor" href="#인증서-발급"><span>인증서 발급</span></a></h4><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 인증서 발급</span></span>
<span class="line">vault <span class="token function">write</span> pki/issue/example-dot-com <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">common_name</span><span class="token operator">=</span><span class="token string">&quot;test.example.com&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">ttl</span><span class="token operator">=</span>24h</span>
<span class="line"></span></code></pre></div></details><h3 id="_7-2-automation-with-vault" tabindex="-1"><a class="header-anchor" href="#_7-2-automation-with-vault"><span>7.2 Automation with Vault</span></a></h3><p>Vault는 다양한 자동화 도구와 통합하여 인증서 관리를 자동화할 수 있습니다.</p><h4 id="자동화-방식-비교" tabindex="-1"><a class="header-anchor" href="#자동화-방식-비교"><span>자동화 방식 비교</span></a></h4><table><thead><tr><th>자동화 방식</th><th>환경</th><th>주요 특징</th><th>적합한 사용 사례</th></tr></thead><tbody><tr><td><strong>Vault Agent</strong></td><td>일반 서버</td><td>템플릿 기반 파일 생성, TTL 모니터링 및 자동 갱신</td><td>단일 서버, VM 환경</td></tr><tr><td><strong>VSO (Vault Secrets Operator)</strong></td><td>Kubernetes</td><td>Kubernetes Secret으로 자동 동기화, CRD 기반 관리</td><td>Kubernetes 클러스터</td></tr><tr><td><strong>Nomad</strong></td><td>Nomad 클러스터</td><td>Job 템플릿을 통한 인증서 주입, 자동 갱신 및 재시작</td><td>Nomad 워크로드 오케스트레이션</td></tr></tbody></table><h4 id="_7-2-1-vault-agent" tabindex="-1"><a class="header-anchor" href="#_7-2-1-vault-agent"><span>7.2.1 Vault Agent</span></a></h4><p>Vault Agent는 템플릿 기반으로 인증서를 자동으로 발급하고 갱신합니다.</p><details class="hint-container details"><summary>Vault Agent</summary><h5 id="vault-agent-구성" tabindex="-1"><a class="header-anchor" href="#vault-agent-구성"><span>Vault Agent 구성</span></a></h5><div class="language-hcl line-numbers-mode has-collapsed-lines collapsed" data-highlighter="prismjs" data-ext="hcl" style="--vp-collapsed-lines:20;"><pre><code class="language-hcl"><span class="line"><span class="token property">pid_file</span> <span class="token punctuation">=</span> <span class="token string">&quot;/root/vault_agent/pidfile&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">auto_auth</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">method</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">type</span> <span class="token punctuation">=</span> <span class="token string">&quot;approle&quot;</span></span>
<span class="line">    <span class="token property">config</span> <span class="token punctuation">=</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">role_id_file_path</span> <span class="token punctuation">=</span> <span class="token string">&quot;/root/vault_agent/roleid&quot;</span></span>
<span class="line">      <span class="token property">secret_id_file_path</span> <span class="token punctuation">=</span> <span class="token string">&quot;/root/vault_agent/secretid&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">sink</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">type</span> <span class="token punctuation">=</span> <span class="token string">&quot;file&quot;</span></span>
<span class="line">    <span class="token property">config</span> <span class="token punctuation">=</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">path</span> <span class="token punctuation">=</span> <span class="token string">&quot;/tmp/vault_agent&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">vault</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">address</span> <span class="token punctuation">=</span> <span class="token string">&quot;http://127.0.0.1:8200&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">template</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">source</span>      <span class="token punctuation">=</span> <span class="token string">&quot;/root/vault_agent/cert.tpl&quot;</span></span>
<span class="line">  <span class="token property">destination</span> <span class="token punctuation">=</span> <span class="token string">&quot;/root/cert/my-app.crt&quot;</span></span>
<span class="line">  <span class="token property">perms</span>       <span class="token punctuation">=</span> <span class="token number">0644</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">template</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">source</span>      <span class="token punctuation">=</span> <span class="token string">&quot;/root/vault_agent/ca.tpl&quot;</span></span>
<span class="line">  <span class="token property">destination</span> <span class="token punctuation">=</span> <span class="token string">&quot;/root/cert/ca.crt&quot;</span></span>
<span class="line">  <span class="token property">perms</span>       <span class="token punctuation">=</span> <span class="token number">0644</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">template</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">source</span>      <span class="token punctuation">=</span> <span class="token string">&quot;/root/vault_agent/key.tpl&quot;</span></span>
<span class="line">  <span class="token property">destination</span> <span class="token punctuation">=</span> <span class="token string">&quot;/root/cert/my-app.key&quot;</span></span>
<span class="line">  <span class="token property">perms</span>       <span class="token punctuation">=</span> <span class="token number">0600</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div><div class="collapsed-lines"></div></div></details><details class="hint-container details"><summary>템플릿 파일 예시</summary><p><strong>cert.tpl</strong>:</p><div class="language-hcl" data-highlighter="prismjs" data-ext="hcl"><pre><code class="language-hcl"><span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span>- <span class="token comment">/* 인증서 템플릿 */</span> -<span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> with secret <span class="token string">&quot;pki_int/issue/example-dot-com&quot;</span> <span class="token string">&quot;common_name=test.example.com&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Data.certificate <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre></div><p><strong>ca.tpl</strong>:</p><div class="language-hcl" data-highlighter="prismjs" data-ext="hcl"><pre><code class="language-hcl"><span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span>- <span class="token comment">/* CA 인증서 템플릿 */</span> -<span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> with secret <span class="token string">&quot;pki_int/issue/example-dot-com&quot;</span> <span class="token string">&quot;common_name=test.example.com&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Data.issuing_ca <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre></div><p><strong>key.tpl</strong>:</p><div class="language-hcl" data-highlighter="prismjs" data-ext="hcl"><pre><code class="language-hcl"><span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span>- <span class="token comment">/* 개인 키 템플릿 */</span> -<span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> with secret <span class="token string">&quot;pki_int/issue/example-dot-com&quot;</span> <span class="token string">&quot;common_name=test.example.com&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Data.private_key <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre></div></details><details class="hint-container details"><summary>Vault Agent 실행</summary><h5 id="vault-agent-실행" tabindex="-1"><a class="header-anchor" href="#vault-agent-실행"><span>Vault Agent 실행</span></a></h5><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Vault Agent 실행</span></span>
<span class="line">vault agent <span class="token parameter variable">-config</span><span class="token operator">=</span>/root/vault_agent/vault_agent.hcl -log-level<span class="token operator">=</span>debug</span>
<span class="line"></span></code></pre></div></details><p>Vault Agent는 인증서의 TTL을 모니터링하고, 만료 전에 자동으로 새 인증서를 발급하여 파일을 업데이트합니다.</p><h5 id="동작-방식-4" tabindex="-1"><a class="header-anchor" href="#동작-방식-4"><span>동작 방식</span></a></h5>`,62),r(d,{code:``}),o[6]||=n(`<h4 id="_7-2-2-vso-vault-secrets-operator" tabindex="-1"><a class="header-anchor" href="#_7-2-2-vso-vault-secrets-operator"><span>7.2.2 VSO (Vault Secrets Operator)</span></a></h4><p>VSO는 Kubernetes 환경에서 Vault 시크릿을 Kubernetes Secret으로 자동 동기화하는 오퍼레이터입니다.</p><details class="hint-container details"><summary>VaultPKISecret CRD</summary><h5 id="vaultpkisecret-crd" tabindex="-1"><a class="header-anchor" href="#vaultpkisecret-crd"><span>VaultPKISecret CRD</span></a></h5><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token punctuation">---</span></span>
<span class="line"><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> secrets.hashicorp.com/v1alpha1</span>
<span class="line"><span class="token key atrule">kind</span><span class="token punctuation">:</span> VaultPKISecret</span>
<span class="line"><span class="token key atrule">metadata</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">namespace</span><span class="token punctuation">:</span> vso<span class="token punctuation">-</span>example</span>
<span class="line">  <span class="token key atrule">name</span><span class="token punctuation">:</span> example<span class="token punctuation">-</span>pki</span>
<span class="line"><span class="token key atrule">spec</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">vaultAuthRef</span><span class="token punctuation">:</span> example<span class="token punctuation">-</span>auth</span>
<span class="line">  <span class="token key atrule">mount</span><span class="token punctuation">:</span> pki</span>
<span class="line">  <span class="token key atrule">name</span><span class="token punctuation">:</span> default</span>
<span class="line">  <span class="token key atrule">commonName</span><span class="token punctuation">:</span> example.com</span>
<span class="line">  <span class="token key atrule">format</span><span class="token punctuation">:</span> pem</span>
<span class="line">  <span class="token key atrule">expiryOffset</span><span class="token punctuation">:</span> 1h</span>
<span class="line">  <span class="token key atrule">ttl</span><span class="token punctuation">:</span> 24h</span>
<span class="line">  <span class="token key atrule">destination</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">create</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">    <span class="token key atrule">name</span><span class="token punctuation">:</span> pki<span class="token punctuation">-</span>secret</span>
<span class="line">    <span class="token key atrule">type</span><span class="token punctuation">:</span> Opaque</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="vaultauth-설정" tabindex="-1"><a class="header-anchor" href="#vaultauth-설정"><span>VaultAuth 설정</span></a></h5><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token punctuation">---</span></span>
<span class="line"><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> secrets.hashicorp.com/v1alpha1</span>
<span class="line"><span class="token key atrule">kind</span><span class="token punctuation">:</span> VaultAuth</span>
<span class="line"><span class="token key atrule">metadata</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">name</span><span class="token punctuation">:</span> example<span class="token punctuation">-</span>auth</span>
<span class="line"><span class="token key atrule">spec</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">method</span><span class="token punctuation">:</span> kubernetes</span>
<span class="line">  <span class="token key atrule">mount</span><span class="token punctuation">:</span> kubernetes</span>
<span class="line">  <span class="token key atrule">kubernetes</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">role</span><span class="token punctuation">:</span> pki<span class="token punctuation">-</span>role</span>
<span class="line">    <span class="token key atrule">serviceAccount</span><span class="token punctuation">:</span> default</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></details><h5 id="동작-방식-5" tabindex="-1"><a class="header-anchor" href="#동작-방식-5"><span>동작 방식</span></a></h5>`,4),r(d,{code:``}),o[7]||=n(`<h4 id="_7-2-3-nomad" tabindex="-1"><a class="header-anchor" href="#_7-2-3-nomad"><span>7.2.3 Nomad</span></a></h4><p>Nomad는 Vault와 통합하여 Job 실행 시 인증서를 자동으로 주입하고 갱신할 수 있습니다.</p><details class="hint-container details"><summary>Nomad Job 예시</summary><h5 id="nomad-job-예시" tabindex="-1"><a class="header-anchor" href="#nomad-job-예시"><span>Nomad Job 예시</span></a></h5><div class="language-hcl line-numbers-mode has-collapsed-lines collapsed" data-highlighter="prismjs" data-ext="hcl" style="--vp-collapsed-lines:20;"><pre><code class="language-hcl"><span class="line">job <span class="token string">&quot;web-service&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">datacenters</span> <span class="token punctuation">=</span> <span class="token punctuation">[</span><span class="token string">&quot;dc1&quot;</span><span class="token punctuation">]</span></span>
<span class="line">  <span class="token property">type</span> <span class="token punctuation">=</span> <span class="token string">&quot;service&quot;</span></span>
<span class="line"></span>
<span class="line">  group <span class="token string">&quot;web&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">count</span> <span class="token punctuation">=</span> <span class="token number">1</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">network</span> <span class="token punctuation">{</span></span>
<span class="line">      port <span class="token string">&quot;https&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">static</span> <span class="token punctuation">=</span> <span class="token number">8443</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># Vault 정책 지정</span></span>
<span class="line">    <span class="token keyword">vault</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">policies</span> <span class="token punctuation">=</span> <span class="token punctuation">[</span><span class="token string">&quot;pki&quot;</span><span class="token punctuation">]</span></span>
<span class="line">      <span class="token property">change_mode</span> <span class="token punctuation">=</span> <span class="token string">&quot;restart&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    task <span class="token string">&quot;nginx&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">driver</span> <span class="token punctuation">=</span> <span class="token string">&quot;docker&quot;</span></span>
<span class="line"></span>
<span class="line">      <span class="token keyword">config</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">image</span> <span class="token punctuation">=</span> <span class="token string">&quot;nginx:latest&quot;</span></span>
<span class="line">        <span class="token property">ports</span> <span class="token punctuation">=</span> <span class="token punctuation">[</span><span class="token string">&quot;https&quot;</span><span class="token punctuation">]</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">      <span class="token comment"># 인증서 템플릿</span></span>
<span class="line">      <span class="token keyword">template</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">data</span> <span class="token punctuation">=</span> <span class="token heredoc string">&lt;&lt;EOH</span>
<span class="line">{{- /* CA 인증서 */ -}}</span>
<span class="line">{{ with secret &quot;pki/issue/example-dot-com&quot; &quot;common_name=web.example.com&quot; &quot;ttl=24h&quot; }}</span>
<span class="line">{{ .Data.issuing_ca }}{{ end }}</span>
<span class="line">EOH</span></span>
<span class="line">        <span class="token property">destination</span> <span class="token punctuation">=</span> <span class="token string">&quot;local/ca.crt&quot;</span></span>
<span class="line">        <span class="token property">change_mode</span> <span class="token punctuation">=</span> <span class="token string">&quot;noop&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">      <span class="token keyword">template</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">data</span> <span class="token punctuation">=</span> <span class="token heredoc string">&lt;&lt;EOH</span>
<span class="line">{{- /* 서버 인증서 */ -}}</span>
<span class="line">{{ with secret &quot;pki/issue/example-dot-com&quot; &quot;common_name=web.example.com&quot; &quot;ttl=24h&quot; }}</span>
<span class="line">{{ .Data.certificate }}{{ end }}</span>
<span class="line">EOH</span></span>
<span class="line">        <span class="token property">destination</span> <span class="token punctuation">=</span> <span class="token string">&quot;local/server.crt&quot;</span></span>
<span class="line">        <span class="token property">change_mode</span> <span class="token punctuation">=</span> <span class="token string">&quot;restart&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">      <span class="token keyword">template</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">data</span> <span class="token punctuation">=</span> <span class="token heredoc string">&lt;&lt;EOH</span>
<span class="line">{{- /* 개인 키 */ -}}</span>
<span class="line">{{ with secret &quot;pki/issue/example-dot-com&quot; &quot;common_name=web.example.com&quot; &quot;ttl=24h&quot; }}</span>
<span class="line">{{ .Data.private_key }}{{ end }}</span>
<span class="line">EOH</span></span>
<span class="line">        <span class="token property">destination</span> <span class="token punctuation">=</span> <span class="token string">&quot;local/server.key&quot;</span></span>
<span class="line">        <span class="token property">change_mode</span> <span class="token punctuation">=</span> <span class="token string">&quot;restart&quot;</span></span>
<span class="line">        <span class="token property">perms</span> <span class="token punctuation">=</span> <span class="token string">&quot;0600&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">      <span class="token comment"># Nginx 설정</span></span>
<span class="line">      <span class="token keyword">template</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">data</span> <span class="token punctuation">=</span> <span class="token heredoc string">&lt;&lt;EOH</span>
<span class="line">server {</span>
<span class="line">    listen 8443 ssl;</span>
<span class="line">    server_name web.example.com;</span>
<span class="line"></span>
<span class="line">    ssl_certificate /secrets/server.crt;</span>
<span class="line">    ssl_certificate_key /secrets/server.key;</span>
<span class="line">    ssl_trusted_certificate /secrets/ca.crt;</span>
<span class="line"></span>
<span class="line">    location / {</span>
<span class="line">        return 200 &quot;Hello from secure service&quot;;</span>
<span class="line">        add_header Content-Type text/plain;</span>
<span class="line">    }</span>
<span class="line">}</span>
<span class="line">EOH</span></span>
<span class="line">        <span class="token property">destination</span> <span class="token punctuation">=</span> <span class="token string">&quot;local/nginx.conf&quot;</span></span>
<span class="line">        <span class="token property">change_mode</span> <span class="token punctuation">=</span> <span class="token string">&quot;restart&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div><div class="collapsed-lines"></div></div></details><details class="hint-container details"><summary>Nomad와 Vault 통합 설정</summary><h5 id="nomad와-vault-통합-설정" tabindex="-1"><a class="header-anchor" href="#nomad와-vault-통합-설정"><span>Nomad와 Vault 통합 설정</span></a></h5><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Nomad에 Vault 통합 활성화</span></span>
<span class="line">nomad agent <span class="token parameter variable">-dev</span> <span class="token punctuation">\\</span></span>
<span class="line">  -vault-enabled<span class="token operator">=</span>true <span class="token punctuation">\\</span></span>
<span class="line">  -vault-address<span class="token operator">=</span>http://127.0.0.1:8200 <span class="token punctuation">\\</span></span>
<span class="line">  -vault-token<span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">cat</span> /tmp/vault-token<span class="token variable">)</span></span> <span class="token punctuation">\\</span></span>
<span class="line">  -vault-create-from-role<span class="token operator">=</span>nomad-cluster</span>
<span class="line"></span></code></pre></div></details><h5 id="동작-방식-6" tabindex="-1"><a class="header-anchor" href="#동작-방식-6"><span>동작 방식</span></a></h5>`,5),r(d,{code:``}),o[8]||=n(`<h5 id="change-mode-옵션" tabindex="-1"><a class="header-anchor" href="#change-mode-옵션"><span>change_mode 옵션</span></a></h5><table><thead><tr><th>옵션</th><th>설명</th></tr></thead><tbody><tr><td><strong>noop</strong></td><td>인증서 변경 시 아무 작업도 하지 않음</td></tr><tr><td><strong>restart</strong></td><td>인증서 변경 시 Task 재시작</td></tr><tr><td><strong>signal</strong></td><td>인증서 변경 시 시그널 전송</td></tr></tbody></table><h3 id="_7-3-ca-만료-및-갱신" tabindex="-1"><a class="header-anchor" href="#_7-3-ca-만료-및-갱신"><span>7.3 CA 만료 및 갱신</span></a></h3><p>Vault PKI Engine에서 Root CA 또는 Intermediate CA가 만료되면 해당 CA로부터 발급된 모든 인증서의 신뢰성이 상실됩니다. CA 만료를 사전에 방지하고 적절히 대응하는 방법을 설명합니다.</p><h4 id="root-ca-만료-시" tabindex="-1"><a class="header-anchor" href="#root-ca-만료-시"><span>Root CA 만료 시</span></a></h4><h5 id="영향-범위" tabindex="-1"><a class="header-anchor" href="#영향-범위"><span>영향 범위</span></a></h5><table><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td><strong>인증서 발급 중단</strong></td><td>Vault는 만료된 Root CA로 새 인증서를 발급할 수 없습니다. <code>vault write pki/issue/...</code> 명령이 실패합니다.</td></tr><tr><td><strong>기존 인증서 신뢰 상실</strong></td><td>Root CA 만료 시점 이후, 해당 Root로부터 발급된 모든 인증서(Intermediate CA, 서버/클라이언트 인증서)가 신뢰되지 않습니다.</td></tr><tr><td><strong>CRL 생성 중단</strong></td><td>Certificate Revocation List 생성도 중단됩니다.</td></tr><tr><td><strong>전체 체인 무효화</strong></td><td>Root CA는 인증서 체인의 최상위이므로, 만료 시 전체 인증서 체인이 무효화됩니다.</td></tr></tbody></table><h5 id="vault의-동작" tabindex="-1"><a class="header-anchor" href="#vault의-동작"><span>Vault의 동작</span></a></h5><ul><li>만료된 Root CA로 인증서 발급 시도 시 오류 반환</li><li>기존에 발급된 인증서는 Root CA 만료 시점까지는 유효하지만, 만료 후에는 신뢰되지 않음</li><li>CA 만료를 자동으로 감지하지 않으므로 수동 모니터링 필요</li></ul><h5 id="대처-방안" tabindex="-1"><a class="header-anchor" href="#대처-방안"><span>대처 방안</span></a></h5><p><strong>1. 새로운 Root CA 생성 및 교체</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 새로운 PKI 마운트에 Root CA 생성</span></span>
<span class="line">vault secrets <span class="token builtin class-name">enable</span> <span class="token parameter variable">-path</span><span class="token operator">=</span>pki-new pki</span>
<span class="line">vault secrets tune -max-lease-ttl<span class="token operator">=</span>87600h pki-new</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 새 Root CA 생성</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-field</span><span class="token operator">=</span>certificate pki-new/root/generate/internal <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">common_name</span><span class="token operator">=</span><span class="token string">&quot;example.com v2&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">ttl</span><span class="token operator">=</span>87600h <span class="token operator">&gt;</span> CA_cert_v2.crt</span>
<span class="line"></span>
<span class="line"><span class="token comment"># CA 및 CRL URL 설정</span></span>
<span class="line">vault <span class="token function">write</span> pki-new/config/urls <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">issuing_certificates</span><span class="token operator">=</span><span class="token string">&quot;http://127.0.0.1:8200/v1/pki-new/ca&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">crl_distribution_points</span><span class="token operator">=</span><span class="token string">&quot;http://127.0.0.1:8200/v1/pki-new/crl&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. Cross-Signing (교차 서명)을 통한 점진적 전환</strong></p><p>기존 Intermediate CA를 새 Root CA로도 서명하여 전환 기간 동안 양쪽 체인 모두 유효하게 유지:</p><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 기존 Intermediate CA의 인증서 가져오기</span></span>
<span class="line">vault <span class="token builtin class-name">read</span> <span class="token parameter variable">-field</span><span class="token operator">=</span>certificate pki_int/cert/ca <span class="token operator">&gt;</span> existing_intermediate.crt</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 새 Root CA로 기존 Intermediate CA 교차 서명</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-format</span><span class="token operator">=</span>json pki-new/root/sign-intermediate <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">csr</span><span class="token operator">=</span>@existing_intermediate.csr <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">format</span><span class="token operator">=</span>pem_bundle <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.data.certificate&#39;</span> <span class="token operator">&gt;</span> cross_signed_intermediate.crt</span>
<span class="line"></span></code></pre></div><p><strong>3. 점진적 마이그레이션</strong></p><ul><li>기존 Root CA와 새 Root CA를 병행 운영</li><li>새 인증서는 새 Root CA로 발급</li><li>기존 인증서는 만료될 때까지 기존 체인 사용</li><li>모든 인증서가 새 체인으로 전환될 때까지 대기</li></ul><h4 id="intermediate-ca-만료-시" tabindex="-1"><a class="header-anchor" href="#intermediate-ca-만료-시"><span>Intermediate CA 만료 시</span></a></h4><h5 id="영향-범위-1" tabindex="-1"><a class="header-anchor" href="#영향-범위-1"><span>영향 범위</span></a></h5><table><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td><strong>인증서 발급 중단</strong></td><td>Vault는 만료된 Intermediate CA로 새 인증서를 발급할 수 없습니다.</td></tr><tr><td><strong>하위 인증서 신뢰 상실</strong></td><td>Intermediate CA 만료 시점 이후, 해당 Intermediate CA로부터 발급된 모든 서버/클라이언트 인증서가 신뢰되지 않습니다.</td></tr><tr><td><strong>부분적 체인 무효화</strong></td><td>해당 Intermediate CA 하위의 인증서 체인만 무효화되며, 다른 Intermediate CA는 영향받지 않습니다.</td></tr></tbody></table><h5 id="vault의-동작-1" tabindex="-1"><a class="header-anchor" href="#vault의-동작-1"><span>Vault의 동작</span></a></h5><ul><li>만료된 Intermediate CA로 인증서 발급 시도 시 오류 반환</li><li>기존에 발급된 인증서는 Intermediate CA 만료 시점까지는 유효</li><li>CA 만료를 자동으로 감지하지 않으므로 수동 모니터링 필요</li></ul><h5 id="대처-방안-1" tabindex="-1"><a class="header-anchor" href="#대처-방안-1"><span>대처 방안</span></a></h5><p><strong>1. 새로운 Intermediate CA 생성</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 새로운 Intermediate CA 엔진 활성화</span></span>
<span class="line">vault secrets <span class="token builtin class-name">enable</span> <span class="token parameter variable">-path</span><span class="token operator">=</span>pki_int_new pki</span>
<span class="line">vault secrets tune -max-lease-ttl<span class="token operator">=</span>43800h pki_int_new</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 새 Intermediate CA CSR 생성</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-format</span><span class="token operator">=</span>json pki_int_new/intermediate/generate/internal <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">common_name</span><span class="token operator">=</span><span class="token string">&quot;example.com Intermediate Authority v2&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.data.csr&#39;</span> <span class="token operator">&gt;</span> pki_intermediate_v2.csr</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Root CA로 새 Intermediate CA 서명</span></span>
<span class="line">vault <span class="token function">write</span> <span class="token parameter variable">-format</span><span class="token operator">=</span>json pki/root/sign-intermediate <span class="token assign-left variable">csr</span><span class="token operator">=</span>@pki_intermediate_v2.csr <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">format</span><span class="token operator">=</span>pem_bundle <span class="token assign-left variable">ttl</span><span class="token operator">=</span><span class="token string">&quot;43800h&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.data.certificate&#39;</span> <span class="token operator">&gt;</span> intermediate_v2.cert.pem</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 새 Intermediate CA 설정</span></span>
<span class="line">vault <span class="token function">write</span> pki_int_new/intermediate/set-signed <span class="token assign-left variable">certificate</span><span class="token operator">=</span>@intermediate_v2.cert.pem</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. Role 마이그레이션</strong></p><p>기존 Role을 새 Intermediate CA로 마이그레이션:</p><div class="language-bash" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 기존 Role 설정 확인</span></span>
<span class="line">vault <span class="token builtin class-name">read</span> pki_int/roles/example-dot-com</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 새 Intermediate CA에 동일한 Role 생성</span></span>
<span class="line">vault <span class="token function">write</span> pki_int_new/roles/example-dot-com <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">allowed_domains</span><span class="token operator">=</span>example.com <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">allow_subdomains</span><span class="token operator">=</span>true <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token assign-left variable">max_ttl</span><span class="token operator">=</span>72h</span>
<span class="line"></span></code></pre></div><p><strong>3. 점진적 전환</strong></p><ul><li>기존 Intermediate CA와 새 Intermediate CA를 병행 운영</li><li>새 인증서는 새 Intermediate CA로 발급</li><li>기존 인증서는 만료될 때까지 기존 체인 사용</li><li>모든 인증서가 새 체인으로 전환될 때까지 대기</li></ul><h4 id="ca-만료-모니터링" tabindex="-1"><a class="header-anchor" href="#ca-만료-모니터링"><span>CA 만료 모니터링</span></a></h4><p>Vault는 CA 만료를 자동으로 감지하지 않으므로, 정기적인 모니터링이 필요합니다.</p><h5 id="만료일-확인-방법" tabindex="-1"><a class="header-anchor" href="#만료일-확인-방법"><span>만료일 확인 방법</span></a></h5><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Root CA 만료일 확인</span></span>
<span class="line">vault <span class="token builtin class-name">read</span> <span class="token parameter variable">-field</span><span class="token operator">=</span>certificate pki/cert/ca <span class="token operator">|</span> <span class="token punctuation">\\</span></span>
<span class="line">    openssl x509 <span class="token parameter variable">-noout</span> <span class="token parameter variable">-dates</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Intermediate CA 만료일 확인</span></span>
<span class="line">vault <span class="token builtin class-name">read</span> <span class="token parameter variable">-field</span><span class="token operator">=</span>certificate pki_int/cert/ca <span class="token operator">|</span> <span class="token punctuation">\\</span></span>
<span class="line">    openssl x509 <span class="token parameter variable">-noout</span> <span class="token parameter variable">-dates</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># JSON 형식으로 만료일 확인</span></span>
<span class="line">vault <span class="token builtin class-name">read</span> <span class="token parameter variable">-format</span><span class="token operator">=</span>json pki/cert/ca <span class="token operator">|</span> <span class="token punctuation">\\</span></span>
<span class="line">    jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.data.certificate&#39;</span> <span class="token operator">|</span> <span class="token punctuation">\\</span></span>
<span class="line">    openssl x509 <span class="token parameter variable">-noout</span> <span class="token parameter variable">-enddate</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="모니터링-권장-사항" tabindex="-1"><a class="header-anchor" href="#모니터링-권장-사항"><span>모니터링 권장 사항</span></a></h5><table><thead><tr><th>CA 유형</th><th>모니터링 주기</th><th>갱신 준비 시기</th></tr></thead><tbody><tr><td><strong>Root CA</strong></td><td>분기별</td><td>만료 1-2년 전부터 새 Root CA 준비</td></tr><tr><td><strong>Intermediate CA</strong></td><td>월별</td><td>만료 6개월-1년 전부터 새 Intermediate CA 준비</td></tr></tbody></table><h5 id="자동화된-모니터링-예시" tabindex="-1"><a class="header-anchor" href="#자동화된-모니터링-예시"><span>자동화된 모니터링 예시</span></a></h5><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># CA 만료일 확인 스크립트</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PKI_MOUNT</span><span class="token operator">=</span><span class="token string">&quot;pki&quot;</span></span>
<span class="line"><span class="token assign-left variable">WARNING_DAYS</span><span class="token operator">=</span><span class="token number">365</span>  <span class="token comment"># 1년 전 경고</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Root CA 만료일 확인</span></span>
<span class="line"><span class="token assign-left variable">CERT</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>vault <span class="token builtin class-name">read</span> <span class="token parameter variable">-field</span><span class="token operator">=</span>certificate $<span class="token punctuation">{</span>PKI_MOUNT<span class="token punctuation">}</span>/cert/ca<span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">EXPIRY</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$CERT</span>&quot;</span> <span class="token operator">|</span> openssl x509 <span class="token parameter variable">-noout</span> <span class="token parameter variable">-enddate</span> <span class="token operator">|</span> <span class="token function">cut</span> <span class="token parameter variable">-d</span><span class="token operator">=</span> <span class="token parameter variable">-f2</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">EXPIRY_EPOCH</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> <span class="token parameter variable">-d</span> <span class="token string">&quot;<span class="token variable">$EXPIRY</span>&quot;</span> +%s<span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">CURRENT_EPOCH</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%s<span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">DAYS_UNTIL_EXPIRY</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$((</span> <span class="token punctuation">(</span>$EXPIRY_EPOCH <span class="token operator">-</span> $CURRENT_EPOCH<span class="token punctuation">)</span> <span class="token operator">/</span> <span class="token number">86400</span> <span class="token variable">))</span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token variable">$DAYS_UNTIL_EXPIRY</span> <span class="token parameter variable">-lt</span> <span class="token variable">$WARNING_DAYS</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;경고: Root CA가 <span class="token variable">\${DAYS_UNTIL_EXPIRY}</span>일 후 만료됩니다!&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;만료일: <span class="token variable">$EXPIRY</span>&quot;</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="ca-갱신-전략" tabindex="-1"><a class="header-anchor" href="#ca-갱신-전략"><span>CA 갱신 전략</span></a></h4><table><thead><tr><th>전략</th><th>설명</th><th>장점</th><th>단점</th></tr></thead><tbody><tr><td><strong>Big Bang 교체</strong></td><td>모든 인증서를 한 번에 새 CA로 전환</td><td>간단하고 빠름</td><td>서비스 중단 위험, 롤백 어려움</td></tr><tr><td><strong>점진적 전환 (Rollover)</strong></td><td>기존 CA와 새 CA를 병행 운영하며 점진적으로 전환</td><td>서비스 중단 없음, 안전함</td><td>복잡하고 시간 소요</td></tr><tr><td><strong>Cross-Signing</strong></td><td>기존 Intermediate CA를 새 Root CA로도 서명</td><td>양쪽 체인 모두 유효, 유연함</td><td>추가 관리 필요</td></tr></tbody></table><div class="hint-container caution"><p class="hint-container-title">Root CA 만료 시 전체 시스템 영향</p><p><strong>Root CA 만료는 전체 PKI 인프라에 치명적인 영향을 미칩니다:</strong></p><ul><li><strong>전체 인증서 체인 무효화</strong>: Root CA가 만료되면 해당 Root로부터 발급된 모든 인증서(Intermediate CA, 서버/클라이언트 인증서)가 신뢰되지 않습니다.</li><li><strong>서비스 중단</strong>: HTTPS 웹사이트, mTLS 서비스, VPN 연결 등 모든 암호화 통신이 실패할 수 있습니다.</li><li><strong>복구 어려움</strong>: Root CA 만료 후에는 즉시 복구가 어렵고, 모든 클라이언트에 새 Root CA를 배포해야 합니다.</li></ul><p><strong>Big Bang 교체 전략의 위험성:</strong></p><ul><li>모든 인증서를 한 번에 교체하는 것은 <strong>서비스 중단 위험</strong>이 매우 높습니다.</li><li>하나의 인증서라도 누락되면 해당 서비스가 즉시 중단됩니다.</li><li>롤백이 어렵고, 문제 발생 시 전체 시스템에 영향을 미칩니다.</li></ul><p><strong>권장 사항:</strong></p><ul><li><strong>절대 Big Bang 교체를 사용하지 마세요</strong>. 점진적 전환(Rollover) 또는 Cross-Signing 방식을 사용하세요.</li><li>Root CA 만료 <strong>최소 1-2년 전</strong>부터 새 Root CA 준비를 시작하세요.</li><li>테스트 환경에서 충분히 검증한 후 프로덕션에 적용하세요.</li></ul></div><h4 id="주의사항" tabindex="-1"><a class="header-anchor" href="#주의사항"><span>주의사항</span></a></h4><div class="hint-container warning"><p class="hint-container-title">CA 만료 대응 시 주의사항</p><ol><li><strong>사전 계획</strong>: CA 만료는 예측 가능하므로 충분한 시간을 두고 계획하세요.</li><li><strong>테스트 환경 검증</strong>: 변경 전후 인증서 체인이 정상적으로 신뢰 및 동작하는지 테스트 환경에서 반드시 검증하세요.</li><li><strong>백업</strong>: CA 교체 전 기존 CA 인증서와 키를 안전하게 백업하세요.</li><li><strong>문서화</strong>: CA 교체 절차와 일정을 문서화하고 관련 팀에 공유하세요.</li><li><strong>모니터링</strong>: CA 교체 후 인증서 발급 및 검증이 정상적으로 동작하는지 모니터링하세요.</li></ol></div><h2 id="참고-자료" tabindex="-1"><a class="header-anchor" href="#참고-자료"><span>참고 자료</span></a></h2><ul><li><a href="https://www.sslmarket.com/blog/comparison-of-acme-est-scep-and-cmpv2-protocols-for-certificate-acquisition" target="_blank" rel="noopener noreferrer">SSLmarket - ACME, EST, SCEP, CMPv2 프로토콜 비교</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc8894" target="_blank" rel="noopener noreferrer">RFC 8894 - SCEP</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7030" target="_blank" rel="noopener noreferrer">RFC 7030 - EST</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc8555" target="_blank" rel="noopener noreferrer">RFC 8555 - ACME</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc4210" target="_blank" rel="noopener noreferrer">RFC 4210 - CMPv2</a></li><li><a href="https://developer.hashicorp.com/vault/docs/secrets/pki" target="_blank" rel="noopener noreferrer">HashiCorp Vault PKI 문서</a></li><li><a href="https://developer.hashicorp.com/vault/docs/platform/k8s/vso" target="_blank" rel="noopener noreferrer">Vault Secrets Operator 문서</a></li></ul>`,45)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};